&espi0 {
	espi_host: espi-host@0 {
		status = "disabled";
		reg = <0x0>;
	};
};

/ {
	espi_emul_0: espi-emul-controller@0 {
		compatible = "zephyr,espi-emul-controller";
		reg = <0x0 0x1>;
		status = "okay";
